1: const { createHash } = require('node:crypto')
2: const { mkdirSync, readFileSync, writeFileSync, existsSync, renameSync, appendFileSync } = require('node:fs')
3: const { join } = require('node:path')
4: 
5: function webDirectory(env) { return env.OMGITHUB_CAPTURE_WEB_DIR || env.OPENCODE_WEB_DIR }
6: // Controller-owned loopback ports never count as project pages: the OpenCode
7: // server default, and cloudflared's default metrics range. Runtime-allocated
8: // controller ports come from the workflow env and $OPENCODE_WEB_DIR/controller-ports.
9: const CONTROLLER_PORTS = [4096, 20241, 20242, 20243, 20244, 20245]
10: const CONTROLLER_PORT_ENV = ['OPENCODE_WEB_PORT', 'OPENCODE_CONTROL_PORT', 'PROJECT_FILE_PORT']
11: const LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]'])
12: function controllerPorts(env = process.env) {
13:   const ports = [...CONTROLLER_PORTS, ...CONTROLLER_PORT_ENV.map(name => env[name])]
14:   const directory = webDirectory(env)
15:   if (directory) try { ports.push(...readFileSync(join(directory, 'controller-ports'), 'utf8').split(/\s+/)) } catch {}
16:   return new Set(ports.map(Number).filter(port => Number.isSafeInteger(port) && port > 0))
17: }
18: function projectOrigins(env = process.env) {
19:   const directory = webDirectory(env)
20:   const port = env.APP_PORT || 3000
21:   const urls = [`http://localhost:${port}`, `http://127.0.0.1:${port}`, `http://[::1]:${port}`]
22:   if (env.APP_URL) urls.push(env.APP_URL)
23:   if (directory) {
24:     try { urls.push(readFileSync(join(directory, 'app-url'), 'utf8').trim()) } catch {}
25:     try { urls.push(...JSON.parse(readFileSync(join(directory, 'project-preview-origins.json'), 'utf8'))) } catch {}
26:   }
27:   return new Set(urls.flatMap(url => { try { return [new URL(url).origin] } catch { return [] } }))
28: }
29: // Returns '' for project pages, otherwise the skip reason.
30: function skipReason(url, env = process.env) {
31:   let parsed
32:   try { parsed = new URL(url) } catch { return 'invalid page URL' }
33:   if (!/^https?:$/.test(parsed.protocol)) return 'non-HTTP page'
34:   if (projectOrigins(env).has(parsed.origin)) return ''
35:   if (LOOPBACK_HOSTS.has(parsed.hostname)) {
36:     const port = Number(parsed.port || (parsed.protocol === 'https:' ? 443 : 80))
37:     return controllerPorts(env).has(port) ? 'controller port' : ''
38:   }
39:   return 'origin not a project preview'
40: }
41: function isProjectPage(url, env = process.env) { return !skipReason(url, env) }
42: function safeOrigin(url) { try { const parsed = new URL(url); return /^https?:$/.test(parsed.protocol) ? parsed.origin : parsed.protocol } catch { return 'invalid' } }
43: function logSkip(reason, url, env) {
44:   const line = `WIP screenshot skipped: ${reason} (${safeOrigin(url)})`
45:   console.error(line)
46:   const web = webDirectory(env)
47:   if (web) try { appendFileSync(join(web, 'wip-capture.log'), `${new Date().toISOString()} ${line}\n`) } catch {}
48: }
49: function imageType(bytes) {
50:   if (bytes.subarray(0, 8).toString('hex') === '89504e470d0a1a0a') return 'image/png'
51:   if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'image/jpeg'
52:   if (bytes.subarray(0, 4).toString() === 'RIFF' && bytes.subarray(8, 12).toString() === 'WEBP') return 'image/webp'
53:   return ''
54: }
55: function queueScreenshot(bytes, metadata, env = process.env) {
56:   const web = webDirectory(env)
57:   if (!web) return null
58:   const reason = skipReason(metadata.page_url, env)
59:   if (reason) { logSkip(reason, metadata.page_url, env); return null }
60:   if (!Buffer.isBuffer(bytes) || !bytes.length || bytes.length > 10 * 1024 * 1024) { logSkip('empty or over 10 MB', metadata.page_url, env); return null }
61:   const type = imageType(bytes)
62:   if (!type) { logSkip('not PNG, JPEG, or WebP', metadata.page_url, env); return null }
63:   const hash = createHash('sha256').update(bytes).digest('hex'), dir = join(web, 'wip-queue')
64:   mkdirSync(dir, { recursive: true })
65:   if (existsSync(join(dir, `${hash}.json`)) || existsSync(join(dir, `${hash}.done`))) return hash
66:   const page = new URL(metadata.page_url); page.search = ''; page.hash = ''; page.username = ''; page.password = ''
67:   const value = { ...metadata, page_url: page.href, captured_at: metadata.captured_at || Date.now(), type, hash }
68:   try { writeFileSync(join(dir, `${hash}.image`), bytes, { flag: 'wx', mode: 0o600 }) } catch (error) { if (error.code !== 'EEXIST') throw error }
69:   const temporary = join(dir, `${hash}.${process.pid}.tmp`)
70:   writeFileSync(temporary, JSON.stringify(value), { mode: 0o600 })
71:   renameSync(temporary, join(dir, `${hash}.json`))
72:   return hash
73: }
