75: // Keep agent screenshots small: CSS-pixel scale (no 2x/3x device pixels) and JPEG
76: // quality 70 when the caller asks for JPEG (type or .jpg/.jpeg path). PNG stays PNG so
77: // file names never lie about their bytes. OMGITHUB_SCREENSHOT_FULL=1 keeps full detail.
78: function shrinkOptions(options, env = process.env) {
79:   if (env.OMGITHUB_SCREENSHOT_FULL === '1') return options
80:   const value = { ...(options && typeof options === 'object' ? options : {}) }
81:   value.scale ??= 'css'
82:   const jpeg = value.type === 'jpeg' || (!value.type && /\.jpe?g$/i.test(value.path || ''))
83:   if (jpeg) value.quality ??= 70
84:   return value
85: }
