87: // Wrap public browser APIs so CLI screenshot, run-code, and locator captures
88: // use the same provenance, including captures that never become OC attachments.
89: function instrument(playwright, env = process.env) {
90:   const patched = Symbol.for('omgithub.wipScreenshot')
91:   function patchScreenshot(prototype, pageFor) {
92:     if (!prototype?.screenshot || prototype.screenshot[patched]) return
93:     const original = prototype.screenshot
94:     const wrapped = async function (...args) {
95:       const page = pageFor(this), page_url = page.url(), captured_at = Date.now()
96:       const bytes = await original.apply(this, [shrinkOptions(args[0], env), ...args.slice(1)])
97:       if (page.url() === page_url) {
98:         try { queueScreenshot(bytes, { page_url, captured_at, browser_session: env.OMGITHUB_BROWSER_SESSION || '', session_id: env.OPENCODE_SESSION_ID || '' }, env) }
99:         catch (error) { console.error('WIP capture deferred:', error.message) }
100:       }
101:       return bytes
102:     }
103:     wrapped[patched] = true
104:     prototype.screenshot = wrapped
105:   }
106:   function pageReady(page) {
107:     patchScreenshot(Object.getPrototypeOf(page), page => page)
108:     patchScreenshot(Object.getPrototypeOf(page.locator('html')), locator => locator.page())
109:   }
110:   function contextReady(context) {
111:     for (const page of context.pages()) pageReady(page)
112:     context.on('page', pageReady)
113:     return context
114:   }
115:   function browserReady(browser) {
116:     for (const context of browser.contexts()) contextReady(context)
117:     const original = browser.newContext.bind(browser)
118:     browser.newContext = async (...args) => contextReady(await original(...args))
119:     return browser
120:   }
121:   for (const type of [playwright.chromium, playwright.firefox, playwright.webkit].filter(Boolean)) {
122:     for (const name of ['launch', 'connect', 'connectOverCDP', 'launchPersistentContext']) {
123:       if (!type[name] || type[name][patched]) continue
124:       const original = type[name].bind(type)
125:       const wrapped = async (...args) => name === 'launchPersistentContext' ? contextReady(await original(...args)) : browserReady(await original(...args))
126:       wrapped[patched] = true; type[name] = wrapped
127:     }
128:   }
129: }
130: module.exports = { shrinkOptions, projectOrigins, controllerPorts, skipReason, isProjectPage, imageType, queueScreenshot, instrument, webDirectory }

