for(let i=0;i<4;i++){let x=61+i*1.3,z=-55+Math.sin(i*2)*2,h=4+Math.random()*2;let p=box(scene,x,groundY(x,z)+h/2,z,.75,h,.7,stoneMat);p.rotation.z=(Math.random()-.5)*.4;}
