 part(new THREE.SphereGeometry(.245,10,8),hair,0,1.62,-.04).scale.set(1,.68,1);
 for(const side of [-1,1]){
  part(new THREE.SphereGeometry(.035,6,6),eyes,side*.09,1.51,.207);
