@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{font-family:'DM Sans',sans-serif;color:#f1eee5;background:#111713;font-synthesis:none;text-rendering:optimizeLegibility;--gold:#d8b978;--goldbright:#f1d49a;--muted:#a9aa9f;--panel:rgba(15,20,18,.84)}*{box-sizing:border-box}html,body,#game-root{width:100%;height:100%;margin:0;overflow:hidden}body{background:#131a17}button,input,select{font:inherit}button{color:inherit}#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,rgba(8,13,12,.87) 0%,rgba(9,14,13,.75) 31%,rgba(9,14,13,.22) 63%,rgba(9,14,13,.12) 100%),linear-gradient(0deg,rgba(7,11,10,.4),transparent 30%,rgba(9,13,12,.14)}.grain{position:absolute;inset:0;pointer-events:none;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E")}.topline{position:absolute;top:31px;left:48px;right:48px;display:flex;align-items:center;gap:12px;z-index:3;font-size:9px;letter-spacing:2.1px;color:#c5c6b8}.sigil{color:var(--gold);font-size:18px}.topline-rule{height:1px;width:62px;background:rgba(216,185,120,.5)}.chapter{color:#858980}.creation{position:absolute;inset:0;z-index:2;transition:opacity .8s,visibility .8s}.creation.hidden{opacity:0;visibility:hidden;pointer-events:none}.creation-left{position:absolute;left:8.1%;top:12.6%;width:410px;max-width:42vw}.eyebrow{font-size:9px;letter-spacing:2.6px;color:var(--gold);display:flex;align-items:center;gap:10px}.eyebrow-line{height:1px;width:24px;background:var(--gold)}h1{font-family:Cinzel,serif;font-size:clamp(46px,6.1vw,76px);line-height:1;letter-spacing:8px;font-weight:500;margin:21px 0 3px;text-shadow:0 3px 24px #151b18}.subtitle{font-family:Cinzel,serif;font-size:13px;letter-spacing:5.5px;color:var(--gold);margin-left:5px}.intro{font-size:12px;line-height:1.75;color:#b9bcb0;max-width:330px;margin:17px 0 24px}.section-label{font-size:9px;letter-spacing:1.7px;color:var(--gold);padding-bottom:10px;border-bottom:1px solid rgba(216,185,120,.23)}.section-label span{color:#e2dfd4;margin-left:12px}.race-list{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;margin:12px 0 12px}.race-card{height:61px;border:1px solid rgba(220,218,203,.13);background:rgba(26,33,30,.56);cursor:pointer;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:4px;transition:.2s;color:#bfc2b7}.race-card:hover{background:rgba(203,176,120,.12);border-color:#a68955}.race-card.active{background:rgba(193,162,100,.18);border-color:var(--gold);box-shadow:inset 0 0 17px rgba(216,185,120,.08)}.race-symbol{font-size:19px;color:#c9ae76;line-height:1}.race-name{font-family:Cinzel,serif;font-size:8px;letter-spacing:.7px}.race-lore{height:40px;color:#adb0a5;font-size:10px;line-height:1.55;border-left:1px solid rgba(216,185,120,.55);padding:0 0 0 11px}.character-fields{display:flex;gap:15px;margin-top:12px}.character-fields label{font-size:8px;letter-spacing:1.5px;color:#aaa99c;display:flex;flex-direction:column;gap:6px;flex:1}.character-fields input,.character-fields select{height:34px;background:rgba(9,14,12,.62);border:1px solid rgba(220,218,203,.18);color:#e8e5d9;padding:0 10px;outline:none;font-size:11px;letter-spacing:.3px}.character-fields select option{background:#18201c}.character-fields input:focus,.character-fields select:focus{border-color:var(--gold)}.begin-btn{width:100%;height:48px;margin-top:14px;border:1px solid #d5b879;background:linear-gradient(110deg,#c9aa6e,#d9bd83);color:#1c211c;display:flex;align-items:center;justify-content:space-between;padding:0 17px;cursor:pointer;font-size:9px;letter-spacing:2px;font-weight:700;transition:.2s}.begin-btn:hover{background:#efd397;transform:translateY(-1px);box-shadow:0 8px 26px #1119}.button-arrow{font-size:17px}.save-note{font-size:8px;letter-spacing:1.7px;color:#85877d;text-align:center;margin-top:13px}.save-note span{color:var(--gold);margin-right:5px}.creation-right{position:absolute;right:9%;top:23%;text-align:right;color:#e5ddc8}.preview-caption{font-family:Cinzel,serif;font-size:10px;letter-spacing:2px;display:flex;gap:15px;justify-content:flex-end;align-items:center}.preview-caption span:last-child{color:var(--gold)}.preview-caption span:first-child{color:#aaa99c}.preview-hint{margin-top:8px;font-size:9px;color:#999b91;letter-spacing:.5px}.creation-footer{position:absolute;bottom:25px;left:48px;right:48px;display:flex;justify-content:space-between;font-size:8px;letter-spacing:1.5px;color:#777d74}
